function rng(seed){let state=(Number(seed)>>>0)||1;return()=>{state=(state+0x6D2B79F5)|0;let t=Math.imul(state^(state>>>15),1|state);t=(t+Math.imul(t^(t>>>7),61|t))^t;return ((t^(t>>>14))>>>0)/4294967296}}
function pick(list,r){return list[Math.floor(r()*list.length)]}
function shuffle(list,r){const copy=[...list];for(let i=copy.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function int(min,max,r){return min+Math.floor(r()*(max-min+1))}
function choice(prompt,answer,options,r,detail=''){return{prompt,answer,choices:shuffle([...new Set(options)],r),detail}}
function koreanPractice(topic,grade,r){
 const row=pick(topic==='vocabulary'?KOREAN_VOCAB[grade<=4?'lower':'upper']:topic==='idiom'?KOREAN_IDIOMS:KOREAN_HANJA,r),[sentence,term,answer,...wrong]=row;
 const prompt=topic==='idiom'?`다음 문장을 읽고 ‘${term}’의 뜻으로 알맞은 것을 고르세요.`:topic==='hanja'?`다음 문장에서 ‘${term}’의 뜻으로 알맞은 것을 고르세요.`:`다음 문장에서 ‘${term}’의 뜻으로 알맞은 것을 고르세요.`;
 return {...choice(prompt,answer,[answer,...wrong],r,sentence),explanation:`‘${sentence}’에서 ‘${term}’은(는) ‘${answer}’라는 뜻입니다.`};
}
function readingSet(size,grade,r){
 const selected=shuffle(READING_SETS[grade<=4?'lower':'upper'],r).slice(0,size/5),items=[];
 for(const passage of selected)for(const [index,row] of passage.questions.entries()){const [prompt,answer,...wrong]=row;items.push({...choice(prompt,answer,[answer,...wrong],r),...(index===0?{readingTitle:passage.title,readingPassage:passage.passage}:{}),readingGroup:passage.title,explanation:`글 「${passage.title}」의 내용과 비교해 보세요.`})}
 return items;
}
function socialTheme(topic,r){const [prompt,answer,...wrong]=pick(SOCIAL_THEME_QUESTIONS[topic],r);return choice(prompt,answer,[answer,...wrong],r)}
